-- Phase A, Snowflake: tables Snowflake writes and SQE reads. One statement per line;
-- @S@ is DATABASE.SCHEMA. Volume and catalog come from the database defaults (see README).
-- INSERT ... SELECT, not VALUES: Snowflake refuses PARSE_JSON and structured casts in VALUES.
CREATE OR REPLACE ICEBERG TABLE @S@.SF_RUN_BASIC (ID INT, NAME STRING, AMOUNT DECIMAL(10,2), TS TIMESTAMP_LTZ(6), NTZ TIMESTAMP_NTZ(6), D DATE, FLAG BOOLEAN, BIG BIGINT, DBL DOUBLE, BIN BINARY, T TIME(6)) ICEBERG_VERSION = 2;
INSERT INTO @S@.SF_RUN_BASIC SELECT 1, 'a', 1.50, '2026-01-02 03:04:05.123456 +00:00'::TIMESTAMP_LTZ, '2026-01-02 03:04:05.123456'::TIMESTAMP_NTZ, '2026-01-02'::DATE, TRUE, 9007199254740993, 1.5, TO_BINARY('CAFE', 'HEX'), '03:04:05.123456'::TIME UNION ALL SELECT 2, 'b', NULL, NULL, NULL, NULL, FALSE, NULL, NULL, NULL, NULL UNION ALL SELECT 3, 'c', -3.25, '1969-12-31 23:59:59 +00:00'::TIMESTAMP_LTZ, '1969-12-31 23:59:59'::TIMESTAMP_NTZ, '1900-01-01'::DATE, NULL, -1, 0.0, TO_BINARY('', 'HEX'), '00:00:00'::TIME;
INSERT INTO @S@.SF_RUN_BASIC SELECT 4, 'd', 4.00, '2026-06-30 12:00:00 +00:00'::TIMESTAMP_LTZ, '2026-06-30 12:00:00'::TIMESTAMP_NTZ, '2026-06-30'::DATE, TRUE, 4, 4.25, TO_BINARY('00FF', 'HEX'), '23:59:59.999999'::TIME;
CREATE OR REPLACE ICEBERG TABLE @S@.SF_RUN_NS (ID INT, NS TIMESTAMP_NTZ(9), TZNS TIMESTAMP_LTZ(9)) ICEBERG_VERSION = 3;
INSERT INTO @S@.SF_RUN_NS SELECT 1, '2026-01-02 03:04:05.123456789'::TIMESTAMP_NTZ(9), '2026-01-02 03:04:05.123456789 +00:00'::TIMESTAMP_LTZ(9) UNION ALL SELECT 2, NULL, NULL;
CREATE OR REPLACE ICEBERG TABLE @S@.SF_RUN_NESTED (ID INT, S OBJECT(a INT, b STRING), ARR ARRAY(INT), M MAP(STRING, INT), ARR_S ARRAY(OBJECT(x DOUBLE))) ICEBERG_VERSION = 2;
INSERT INTO @S@.SF_RUN_NESTED SELECT 1, {'a': 1, 'b': 'x'}::OBJECT(a INT, b STRING), [1, 2, NULL]::ARRAY(INT), {'k': 1, 'j': 2}::MAP(STRING, INT), [{'x': 1.0}]::ARRAY(OBJECT(x DOUBLE)) UNION ALL SELECT 2, NULL, []::ARRAY(INT), {}::MAP(STRING, INT), NULL;
CREATE OR REPLACE ICEBERG TABLE @S@.SF_RUN_PART (ID INT, REGION STRING, TS TIMESTAMP_NTZ(6)) PARTITION BY (REGION, MONTH(TS)) ICEBERG_VERSION = 2;
INSERT INTO @S@.SF_RUN_PART SELECT 1, 'eu', '2026-01-01 00:00:00'::TIMESTAMP_NTZ UNION ALL SELECT 2, 'us', '2026-02-01 00:00:00'::TIMESTAMP_NTZ UNION ALL SELECT 3, 'eu', '2026-03-01 00:00:00'::TIMESTAMP_NTZ;
CREATE OR REPLACE ICEBERG TABLE @S@.SF_RUN_V2 (ID INT, NAME STRING) ICEBERG_VERSION = 2;
INSERT INTO @S@.SF_RUN_V2 SELECT ROW_NUMBER() OVER (ORDER BY SEQ4()), 'n' || ROW_NUMBER() OVER (ORDER BY SEQ4()) FROM TABLE(GENERATOR(ROWCOUNT => 100));
DELETE FROM @S@.SF_RUN_V2 WHERE ID % 10 = 0;
UPDATE @S@.SF_RUN_V2 SET NAME = 'sf-upd' WHERE ID IN (5, 15);
CREATE OR REPLACE ICEBERG TABLE @S@.SF_RUN_V3 (ID INT, NAME STRING) ICEBERG_VERSION = 3;
INSERT INTO @S@.SF_RUN_V3 SELECT ROW_NUMBER() OVER (ORDER BY SEQ4()), 'n' || ROW_NUMBER() OVER (ORDER BY SEQ4()) FROM TABLE(GENERATOR(ROWCOUNT => 100));
DELETE FROM @S@.SF_RUN_V3 WHERE ID % 10 = 0;
UPDATE @S@.SF_RUN_V3 SET NAME = 'sf-upd' WHERE ID IN (5, 15);
-- Merge-on-read: Snowflake rewrites small tables copy-on-write whatever the setting, so these
-- hold 1M rows. The DELETE writes a position delete file (V2) or a deletion vector (V3); a read
-- that crosses a deleted row skips inside a 512-value DELTA_BINARY_PACKED miniblock (parquet >= 59.3.2).
CREATE OR REPLACE ICEBERG TABLE @S@.SF_RUN_MOR_V2 (ID INT, NAME STRING) ICEBERG_VERSION = 2 ICEBERG_MERGE_ON_READ_BEHAVIOR = 'enabled';
INSERT INTO @S@.SF_RUN_MOR_V2 SELECT ROW_NUMBER() OVER (ORDER BY SEQ4()), 'n' || ROW_NUMBER() OVER (ORDER BY SEQ4()) FROM TABLE(GENERATOR(ROWCOUNT => 1000000));
DELETE FROM @S@.SF_RUN_MOR_V2 WHERE ID IN (3, 4) OR ID % 100000 = 0;
UPDATE @S@.SF_RUN_MOR_V2 SET NAME = 'sf-upd' WHERE ID = 5;
CREATE OR REPLACE ICEBERG TABLE @S@.SF_RUN_MOR_V3 (ID INT, NAME STRING) ICEBERG_VERSION = 3 ICEBERG_MERGE_ON_READ_BEHAVIOR = 'enabled';
INSERT INTO @S@.SF_RUN_MOR_V3 SELECT ROW_NUMBER() OVER (ORDER BY SEQ4()), 'n' || ROW_NUMBER() OVER (ORDER BY SEQ4()) FROM TABLE(GENERATOR(ROWCOUNT => 1000000));
DELETE FROM @S@.SF_RUN_MOR_V3 WHERE ID IN (3, 4) OR ID % 100000 = 0;
UPDATE @S@.SF_RUN_MOR_V3 SET NAME = 'sf-upd' WHERE ID = 5;
CREATE OR REPLACE ICEBERG TABLE @S@.SF_RUN_VARIANT (ID INT, V VARIANT) ICEBERG_VERSION = 3;
INSERT INTO @S@.SF_RUN_VARIANT SELECT 1, PARSE_JSON('{"a": 1, "b": [1, 2], "c": {"d": "x"}}') UNION ALL SELECT 2, PARSE_JSON('42') UNION ALL SELECT 3, NULL;
CREATE OR REPLACE ICEBERG TABLE @S@.SF_RUN_GEO (ID INT, G GEOMETRY) ICEBERG_VERSION = 3;
INSERT INTO @S@.SF_RUN_GEO SELECT 1, TO_GEOMETRY('POINT(1 2)', 4326) UNION ALL SELECT 2, TO_GEOMETRY('POLYGON((0 0,4 0,4 3,0 3,0 0))', 4326) UNION ALL SELECT 3, NULL;
CREATE OR REPLACE ICEBERG TABLE @S@.SF_RUN_GEOG (ID INT, G GEOGRAPHY) ICEBERG_VERSION = 3;
INSERT INTO @S@.SF_RUN_GEOG SELECT 1, TO_GEOGRAPHY('POINT(1 2)') UNION ALL SELECT 2, TO_GEOGRAPHY('LINESTRING(0 0,1 1)') UNION ALL SELECT 3, NULL;
CREATE OR REPLACE ICEBERG TABLE @S@.SF_RUN_EVO (ID INT, NAME STRING, AMOUNT DECIMAL(10,2)) ICEBERG_VERSION = 2;
INSERT INTO @S@.SF_RUN_EVO SELECT 1, 'a', 1.50 UNION ALL SELECT 2, 'b', 2.25;
ALTER ICEBERG TABLE @S@.SF_RUN_EVO ADD COLUMN EXTRA STRING;
INSERT INTO @S@.SF_RUN_EVO SELECT 3, 'c', 3.00, 'x3';
ALTER ICEBERG TABLE @S@.SF_RUN_EVO ALTER COLUMN AMOUNT SET DATA TYPE DECIMAL(12,2);
INSERT INTO @S@.SF_RUN_EVO SELECT 4, 'd', 4000000000.00, 'x4';
ALTER ICEBERG TABLE @S@.SF_RUN_EVO RENAME COLUMN NAME TO LABEL;
ALTER ICEBERG TABLE @S@.SF_RUN_EVO ADD COLUMN D STRING;
INSERT INTO @S@.SF_RUN_EVO SELECT 5, 'e', 5.00, 'x5', 'new-d';
